// zmove-status VERIFY (independent): 2v2 oracle cases ZV01-ZV26 (USUM Z-Moves) and MV01-MV13 (SwSh Max Moves): the
// effects a damaging move's Z-Move or Max Move does NOT carry from its base move (pinned Showdown c23d2e94
// sim/battle-actions.ts getActiveZMove / getActiveMaxMove), and the converted move's own (signature Z-Moves' contact, Guardian
// of Alola's damageCallback, Max Moves' stage, weather, terrain), seen through a later move in the same turn.
// Level 50, 31 IVs, Serious, 0 EVs: Speed = base + 20.
import type { Case, CaseAction, CaseMon, SlotId } from "../../2v2/verify/case-types";

type Slot = CaseMon & { action: CaseAction };
const mon = (species: string, ability: string, extra: Partial<CaseMon> = {}): CaseMon => ({ species, ability, ...extra });
const act = (m: CaseMon, move: string | null, target?: SlotId): Slot => ({ ...m, action: { move, ...(target ? { target } : {}) } });
const idle = (m: CaseMon): Slot => act(m, null);
const S = (a: Slot, b: Slot, c: Slot, d: Slot): Case["slots"] => ({ "own-left": a, "own-right": b, "opponent-left": c, "opponent-right": d });
const z = (species: string, ability: string, item: string, extra: Partial<CaseMon> = {}) => mon(species, ability, { item, choice: "zmove", ...extra });
const dmax = (species: string, ability: string, extra: Partial<CaseMon> = {}) => mon(species, ability, { choice: "dynamax", ...extra });
const snorlax = mon("Snorlax", "Thick Fat");
const blastoise = mon("Blastoise", "Torrent");
const blissey = mon("Blissey", "Natural Cure");
const hariyama = mon("Hariyama", "Thick Fat");
const OL: SlotId = "opponent-left", OR: SlotId = "opponent-right", ML: SlotId = "own-left", MR: SlotId = "own-right";

